<?php require_once __DIR__.'/_base.php'; $title='Bookings'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $st=$pdo->query('SELECT b.*,u.name user_name,p.name provider_name,s.service_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN providers p ON p.id=b.provider_id JOIN services s ON s.id=b.service_id ORDER BY b.created_at DESC');?><h2>All Bookings</h2><div class="service-card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>User</th><th>Provider</th><th>Service</th><th>Date</th><th>Value</th><th>Status</th></tr></thead><tbody><?php foreach($st->fetchAll() as $b):?><tr><td>#<?=$b['id']?></td><td><?=e($b['user_name'])?></td><td><?=e($b['provider_name'])?></td><td><?=e($b['service_name'])?></td><td><?=e($b['booking_date'])?></td><td>PKR <?=number_format($b['charges'],2)?></td><td><?=badge($b['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>